import { taskApi } from '@silent-pix/shared'

import type { TaskListItem } from '@silent-pix/shared'

const images: string[] = [
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
]

const baseTasks = [
    ['1005', 'queued', '2026-07-06T08:04:00.000Z'],
    ['1004', 'running', '2026-07-06T08:03:00.000Z'],
    ['1003', 'done', '2026-07-06T08:02:00.000Z', [images[0]!]],
    ['1002', 'done', '2026-07-06T08:01:00.000Z', [images[1]!]],
    ['1001', 'done', '2026-07-06T08:00:00.000Z', [images[2]!, images[1]!, images[0]!]],
] as const

export const mockTasks: TaskListItem[] = baseTasks.map(([id, status, createdAt, images]) => ({
    id,
    status,
    createdAt,
    thumbnail: images ? images[0] : undefined
}))

taskApi.getTasksResponse.parse({ items: mockTasks })
